    if not afile.endswith(".tar.bz2"):
        return os.path.splitext(afile)[0]
    if not afile.endswith(".tar.xz"):
        return os.path.splitext(afile)[0]
    if not afile.endswith(".tar"):
        return os.path.splitext(afile)[0]
    return os.path.splitext(afile)[0]


