                ds = int.from_bytes(value.data, 'little', signed=True)
            except Exception as e:
                pass
            if type(ds) is not int and len(ds) < 1:
                try:
                    ds = value.data.decode('utf-8')
                except Exception as e:
                    pass

        lno = "{:<10}".format(
            pt.lineno if do_print_line_no or pstart else '')
        addr = "{:<5}".format(key)
